// Typed access to the vendored static assets, mirroring upstream's
// module-level reads of api/static/* (api_resource.py:95-121). The JSON blob
// is generated by scripts/generate-assets.ts — see that file for why the
// assets are embedded rather than imported through wrangler `rules`.

import rawGenerated from "./assets.gen.txt";

/**
 * The asset blob is parsed on FIRST USE, not at module scope.
 *
 * It is ~313KB — about 60% of the whole bundle — and a JSON import would be
 * inlined as an object literal that every isolate materialises at startup,
 * including the ones that only answer /search and never read an asset. That
 * startup cost lands on whichever request arrives first in a fresh isolate,
 * against the free plan's 10ms-per-request CPU limit, and search-as-you-type
 * keeps producing fresh isolates. Kept as text, /search isolates never touch
 * it at all.
 */
interface GeneratedAssets {
	text: Record<string, string>;
	binaryBase64: Record<string, string>;
	hashes: Record<string, string>;
}

let parsed: GeneratedAssets | null = null;
function generated(): GeneratedAssets {
	parsed ??= JSON.parse(rawGenerated) as GeneratedAssets;
	return parsed;
}

/** Upstream _serve_static_file reads by filename; unknown names are a bug here (upstream would 404). */
export function staticText(filename: string): string {
	const content = generated().text[filename];
	if (content === undefined) {
		throw new Error(`Unknown static asset: ${filename}`);
	}
	return content;
}

function decodeBase64(b64: string): Uint8Array {
	const raw = atob(b64);
	const bytes = new Uint8Array(raw.length);
	for (let i = 0; i < raw.length; i++) {
		bytes[i] = raw.charCodeAt(i);
	}
	return bytes;
}

function staticBinary(filename: string): Uint8Array {
	const b64 = generated().binaryBase64[filename];
	if (b64 === undefined) {
		throw new Error(`Unknown static asset: ${filename}`);
	}
	return decodeBase64(b64);
}

// Upstream reads these at import time; here they are memoised on first use, so
// an isolate that only answers /search never decodes them (see generated()).
let faviconIco: Uint8Array | null = null;
export function faviconIcoBytes(): Uint8Array {
	faviconIco ??= staticBinary("favicon.ico");
	return faviconIco;
}
let socialPreview: Uint8Array | null = null;
export function socialPreviewBytes(): Uint8Array {
	socialPreview ??= staticBinary("social-preview.webp");
	return socialPreview;
}

// Upstream _STYLES_CSS_HASH / _APP_MIN_JS_HASH / _CARD_JS_HASH
// (api_resource.py:108-110): sha256 hex prefix of the file bytes, or None when
// the file is absent. All three files exist in this port (app.min.js is built
// by generate-assets.ts), so the hashes are always strings.
export function stylesCssHash(): string {
	return generated().hashes["styles.css"] ?? "";
}
export function appMinJsHash(): string {
	return generated().hashes["app.min.js"] ?? "";
}
export function cardJsHash(): string {
	return generated().hashes["card.js"] ?? "";
}

// Shared fragments (api_resource.py:117-121), read on first use rather than at
// import so /search isolates never parse the asset blob.
export function faviconHtml(): string {
	return staticText("fragments/favicon.html");
}
export function preconnectsHtml(): string {
	return staticText("fragments/preconnects.html");
}
export function fontsHtml(): string {
	return staticText("fragments/fonts.html");
}
export function cssHtml(): string {
	return staticText("fragments/css.html");
}
export function footerHtml(): string {
	return staticText("fragments/footer.html");
}
